export const partnersMarkup = "<style>\n  #partners { background: #edf5f2; color: #073b3c; scroll-margin-top: 5rem; padding: 5rem 1.25rem; }\n  #partners .partners-wrap { max-width: 1120px; margin: 0 auto; }\n  #partners .partners-kicker { color: #218d87; font-size: .875rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; margin-bottom: .75rem; }\n  #partners h2 { font-size: clamp(1.875rem, 4vw, 3rem); font-weight: 700; line-height: 1.15; max-width: 920px; }\n  #partners .partners-intro { max-width: 780px; font-size: 1.125rem; line-height: 1.7; margin-top: 1.5rem; color: #48615f; }\n  #partners .partners-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.5rem; margin-top: 2.5rem; }\n  #partners .partners-card { background: #fff; border: 1px solid #d5e5df; border-radius: 1.5rem; padding: 2rem; }\n  #partners .partners-type { display: inline-block; padding: .35rem .8rem; border-radius: 99px; background: #e5f4ef; color: #187a75; font-size: .8rem; font-weight: 700; margin-bottom: 1.25rem; }\n  #partners h3 { font-size: 1.45rem; font-weight: 700; line-height: 1.35; margin-bottom: 1rem; }\n  #partners .partners-card p { color: #48615f; line-height: 1.7; }\n  #partners ul { list-style: none; margin: 1.3rem 0 0; padding: 0; }\n  #partners li { padding-left: 1.25rem; position: relative; margin-top: .65rem; line-height: 1.6; }\n  #partners li::before { content: ''; position: absolute; left: 0; top: .65em; width: .4rem; height: .4rem; background: #2ab9ad; border-radius: 50%; }\n  #partners .partners-model { background: #073b3c; color: #f3faf7; border-radius: 1.5rem; margin-top: 1.5rem; padding: 2rem; }\n  #partners .partners-model p { max-width: 850px; line-height: 1.8; color: #d2e5df; }\n  #partners .partners-model strong { color: #ff982f; }\n  #partners .partners-status { margin-top: 1.25rem; font-size: .9rem; line-height: 1.7; color: #48615f; }\n  @media (max-width: 640px) { #partners { padding: 4rem 1.25rem; } #partners .partners-grid { grid-template-columns: 1fr; } #partners .partners-card, #partners .partners-model { padding: 1.5rem; } }\n</style>\n<div class=\"partners-wrap\">\n  <p class=\"partners-kicker\">Магазинам и рыболовным угодьям</p>\n  <h2>Помогите рыбакам найти ваш магазин или водоём</h2>\n  <p class=\"partners-intro\">Рыбный Прогноз объединяет людей, которые выбирают место для рыбалки и готовят снасти. Для рыболовных магазинов, владельцев платных водоёмов и баз отдыха мы планируем рекламные размещения рядом с полезной информацией о подготовке к поездке.</p>\n  <div class=\"partners-grid\">\n    <article class=\"partners-card\">\n      <span class=\"partners-type\">Где купить снасти</span>\n      <h3>Рыболовным магазинам и производителям</h3>\n      <p>Расскажите о снастях, наживке и прикормке аудитории, которая собирается на рыбалку и выбирает, что взять с собой.</p>\n      <ul>\n        <li>Планируем карточки магазинов и рекламные блоки о товарах.</li>\n        <li>Адрес, сайт и ассортимент помогут рыбаку выбрать, где купить нужное.</li>\n        <li>Формат подойдёт местным магазинам, торговым сетям и производителям снастей.</li>\n      </ul>\n    </article>\n    <article class=\"partners-card\">\n      <span class=\"partners-type\">Куда поехать на рыбалку</span>\n      <h3>Платным водоёмам, угодьям и базам отдыха</h3>\n      <p>Помогите рыбакам узнать о месте для поездки: какие виды рыбы встречаются, как добраться и на каких условиях можно ловить.</p>\n      <ul>\n        <li>Планируем карточки водоёмов и баз с описанием условий рыбалки.</li>\n        <li>В карточке можно будет представить инфраструктуру, правила и контакты.</li>\n        <li>Рекламное размещение познакомит с вашим предложением тех, кто выбирает место отдыха.</li>\n      </ul>\n    </article>\n  </div>\n  <div class=\"partners-model\">\n    <h3>Для рыбаков — бесплатно</h3>\n    <p>Основная бизнес-модель проекта — <strong>рекламные размещения</strong> магазинов, производителей снастей, платных водоёмов и баз отдыха. За счёт этого планируем поддерживать бесплатный базовый доступ к прогнозу и рекомендациям. Платное продвижение будем отмечать отдельно от информационных рекомендаций.</p>\n  </div>\n  <p class=\"partners-status\">Партнёрское направление находится на этапе подготовки. Форматы и условия размещения ещё обсуждаются; реальные рекламодатели и их предложения появятся после согласования.</p>\n</div>";
